"""Text truncation, chunking and markdown helpers."""

from __future__ import annotations

import json
from typing import Any

_DEFAULT_SUFFIX = "…"


def content_to_text(content: str | list[Any] | None) -> str:
    """把 LangChain 消息的 ``content`` 归一化成纯文本。

    ``content`` 可能是字符串，也可能是内容块列表（如
    ``[{"type": "text", "text": "..."}]``，或 Anthropic 风格的 dict 块）。
    """
    if content is None:
        return ""
    if isinstance(content, str):
        return content
    parts: list[str] = []
    for block in content:
        if isinstance(block, str):
            parts.append(block)
        elif isinstance(block, dict):
            text = block.get("text")
            if isinstance(text, str):
                parts.append(text)
    return "".join(parts)


def truncate(text: str, limit: int, *, suffix: str = _DEFAULT_SUFFIX) -> str:
    """按字符数截断文本，并在结尾标注被截断的长度。"""
    if limit <= 0 or len(text) <= limit:
        return text
    dropped = len(text) - limit
    return f"{text[:limit]}{suffix}（已截断 {dropped} 字）"


def stringify_tool_result(result: Any, *, limit: int | None = None) -> str:
    """把工具返回值转成可回填给模型的字符串。

    - ``str`` 直接返回；
    - 其它类型走 ``json.dumps``，无法序列化时回退到 ``str()``。
    """
    if isinstance(result, str):
        text = result
    else:
        try:
            text = json.dumps(result, ensure_ascii=False, default=str)
        except (TypeError, ValueError):
            text = str(result)
    return truncate(text, limit) if limit is not None else text


__all__ = ["content_to_text", "stringify_tool_result", "truncate"]

"""Secret loading and redaction helpers."""

from __future__ import annotations

import re
from typing import Any

#: 与密钥相关的字段名模式。命中后其值在日志与 ``config show`` 中被打码。
_SENSITIVE_NAME = re.compile(
    r"(?:api[_-]?key|apikey|secret|token|password|passwd|credential|authorization)",
    re.IGNORECASE,
)

MASK = "********"


def is_sensitive(name: str) -> bool:
    """字段名是否属于敏感字段。"""
    return bool(_SENSITIVE_NAME.search(name))


def mask(value: str, *, keep: int = 4) -> str:
    """保留首尾少量字符用于辨认，其余打码。"""
    if not value:
        return ""
    if len(value) <= keep + 2:
        return MASK
    return f"{value[:keep]}{MASK}"


def redact(value: Any) -> Any:
    """递归打码字典/列表中的敏感字段值。

    非敏感字段原样保留，方便排查配置问题。
    """
    if isinstance(value, dict):
        return {
            key: (mask(item) if isinstance(item, str) and is_sensitive(str(key)) else redact(item))
            for key, item in value.items()
        }
    if isinstance(value, (list, tuple)):
        return [redact(item) for item in value]
    return value


__all__ = ["MASK", "is_sensitive", "mask", "redact"]

