"""Chat model factory: provider, base_url, fallbacks, retries."""

from __future__ import annotations

from dataclasses import dataclass
from typing import Any

from langchain_core.language_models.chat_models import BaseChatModel
from langchain_core.language_models.fake_chat_models import GenericFakeChatModel

from doudou.agent.testing import ScriptedChatModel, demo_model
from doudou.config.schema import ModelConfig
from doudou.config.settings import Secrets
from doudou.observability.logging import get_logger

logger = get_logger(__name__)

#: 离线模型前缀：``scripted:demo``。
SCRIPTED_PREFIX = "scripted:"

#: provider -> 该 provider 需要的环境变量（仅用于给出可操作的报错提示）。
PROVIDER_CREDENTIALS: dict[str, str] = {
    "openai": "OPENAI_API_KEY",
    "azure_openai": "AZURE_OPENAI_API_KEY",
    "anthropic": "ANTHROPIC_API_KEY",
    "deepseek": "DEEPSEEK_API_KEY",
    "google_genai": "GOOGLE_API_KEY",
    "google_vertexai": "GOOGLE_APPLICATION_CREDENTIALS",
    "groq": "GROQ_API_KEY",
    "mistralai": "MISTRAL_API_KEY",
    "openrouter": "OPENROUTER_API_KEY",
    "ollama": "",
}

#: provider -> 该 provider 读取 base_url 的官方环境变量名。
PROVIDER_BASE_URL_ENV: dict[str, str] = {
    "openai": "OPENAI_BASE_URL",
    "deepseek": "DEEPSEEK_API_BASE",
    "anthropic": "ANTHROPIC_BASE_URL",
    "openrouter": "OPENROUTER_BASE_URL",
    "ollama": "OLLAMA_HOST",
}


class ModelBuildError(RuntimeError):
    """无法构造模型时抛出，消息里会带上可操作的修复建议。"""


@dataclass(frozen=True, slots=True)
class ModelSpec:
    """解析后的 ``provider:model`` 描述。"""

    raw: str
    provider: str | None
    model: str

    @property
    def is_scripted(self) -> bool:
        return self.provider == "scripted"


def parse_spec(spec: str) -> ModelSpec:
    """拆分 ``provider:model``。

    - ``openai:gpt-5.5``   → provider=openai, model=gpt-5.5
    - ``gpt-5.5``          → provider=None（由 langchain 自行推断）
    - ``scripted:demo``    → 内置离线模型
    """
    raw = spec.strip()
    if not raw:
        raise ModelBuildError("模型标识为空，请在 config 的 model.primary 或 --model 中指定")
    provider, sep, model = raw.partition(":")
    if not sep:
        return ModelSpec(raw=raw, provider=None, model=raw)
    # ollama:llama3 这类没有冒号的 provider 前缀也要能识别
    return ModelSpec(raw=raw, provider=provider.strip().lower(), model=model.strip())


def credential_hint(spec: ModelSpec) -> tuple[str, str] | None:
    """返回 ``(环境变量名, 提示语)``；该 provider 不需要凭据时返回 ``None``。"""
    if spec.provider is None or spec.is_scripted:
        return None
    env_name = PROVIDER_CREDENTIALS.get(spec.provider)
    if env_name is None:
        # 未知 provider：langchain 自己会报错，这里不拦。
        return None
    if not env_name:
        return None
    return env_name, f"模型 {spec.raw} 需要 {env_name}，请在 .env 中设置"


def build_model(
    config: ModelConfig,
    *,
    secrets: Secrets | None = None,
    spec: str | None = None,
    extra: dict[str, Any] | None = None,
) -> BaseChatModel:
    """按配置构造聊天模型。

    Args:
        config: ``config.model`` 段。
        secrets: 凭据来源；缺省时由 langchain 直接读环境变量。
        spec: 覆盖 ``config.primary``（CLI 的 ``--model``）。
        extra: 追加给 ``init_chat_model`` 的参数。

    Raises:
        ModelBuildError: 标识非法、缺少 provider 包或缺少凭据。
    """
    resolved = parse_spec(spec or config.primary)

    if resolved.is_scripted:
        return _build_scripted(resolved)

    kwargs: dict[str, Any] = {
        "temperature": config.temperature,
        "max_tokens": config.max_tokens,
        "timeout": config.timeout,
        "max_retries": config.max_retries,
    }
    base_url = config.base_url or _secret_base_url(resolved, secrets)
    if base_url:
        kwargs["base_url"] = base_url
    api_key = _secret_api_key(resolved, secrets)
    if api_key:
        kwargs["api_key"] = api_key
    kwargs.update(extra or {})
    kwargs = {key: value for key, value in kwargs.items() if value is not None}

    from langchain.chat_models import init_chat_model

    try:
        return init_chat_model(resolved.raw, **kwargs)
    except ImportError as exc:
        provider = resolved.provider or "<无法推断>"
        raise ModelBuildError(
            f"缺少 provider {provider!r} 的依赖包。安装对应的 langchain 集成包后重试，"
            f"例如 `uv sync --extra anthropic`。原始错误：{exc}"
        ) from exc
    except Exception as exc:  # noqa: BLE001 - 统一转成可读错误
        hint = credential_hint(resolved)
        suffix = f"\n提示：{hint[1]}" if hint else ""
        raise ModelBuildError(f"构造模型 {resolved.raw!r} 失败：{exc}{suffix}") from exc


def _build_scripted(resolved: ModelSpec) -> BaseChatModel:
    """内置离线模型：不访问网络，用于 CI 与本地自检。"""
    name = resolved.model or "demo"
    if name in {"demo", "offline"}:
        logger.info("model.scripted", name=name)
        return demo_model()
    if name.startswith("echo:"):
        return GenericFakeChatModel(messages=iter([name.removeprefix("echo:")]))
    raise ModelBuildError(
        f"未知的离线模型 {name!r}，可用值：scripted:demo、scripted:echo:<文本>"
    )


def _secret_api_key(resolved: ModelSpec, secrets: Secrets | None) -> str | None:
    if secrets is None or resolved.provider is None:
        return None
    field = PROVIDER_CREDENTIALS.get(resolved.provider)
    if not field:
        return None
    return getattr(secrets, field.lower(), None)


def _secret_base_url(resolved: ModelSpec, secrets: Secrets | None) -> str | None:
    if secrets is None or resolved.provider is None:
        return None
    if resolved.provider == "openai":
        return secrets.openai_base_url
    return None


def build_fallback_models(
    config: ModelConfig, *, secrets: Secrets | None = None
) -> list[BaseChatModel]:
    """构造 fallback 模型列表；单个失败只告警，不影响主链路。"""
    models: list[BaseChatModel] = []
    for spec in config.fallbacks:
        try:
            models.append(build_model(config, secrets=secrets, spec=spec))
        except ModelBuildError as exc:
            logger.warning("model.fallback_build_failed", spec=spec, error=str(exc))
    return models


__all__ = [
    "PROVIDER_CREDENTIALS",
    "SCRIPTED_PREFIX",
    "ModelBuildError",
    "ModelSpec",
    "build_fallback_models",
    "build_model",
    "credential_hint",
    "parse_spec",
]

"""Discover SKILL.md directories and validate frontmatter."""

from __future__ import annotations

import re
from collections.abc import Iterable
from dataclasses import dataclass
from pathlib import Path
from typing import Any

import yaml

from doudou.observability.logging import get_logger

logger = get_logger(__name__)

SKILL_FILENAME = "SKILL.md"

_FRONTMATTER = re.compile(r"^---\s*\r?\n(.*?)\r?\n---\s*(?:\r?\n|$)", re.DOTALL)
_NAME_PATTERN = re.compile(r"^[a-z0-9]+(?:-[a-z0-9]+)*$")


class SkillError(ValueError):
    """Skill 目录或 frontmatter 不合法。"""


@dataclass(frozen=True, slots=True)
class SkillInfo:
    """一个已发现的 Skill。"""

    name: str
    description: str
    path: Path
    #: 完整正文（frontmatter 之后的部分）。
    body: str = ""

    @property
    def directory(self) -> Path:
        return self.path.parent

    @property
    def extra(self) -> dict[str, Any]:
        return dict(self._extra)

    #: frontmatter 中除 name/description 外的其它字段。
    _extra: dict[str, Any] = None  # type: ignore[assignment]


def parse_frontmatter(text: str, *, source: Path | None = None) -> tuple[dict[str, Any], str]:
    """拆分 ``SKILL.md`` 的 frontmatter 与正文。"""
    match = _FRONTMATTER.match(text)
    if match is None:
        where = f"（{source}）" if source else ""
        raise SkillError(f"缺少 YAML frontmatter{where}：文件必须以 '---' 开头并以 '---' 结束。")
    raw = match.group(1)
    try:
        data = yaml.safe_load(raw) or {}
    except yaml.YAMLError as exc:
        raise SkillError(f"frontmatter 不是合法 YAML：{exc}") from exc
    if not isinstance(data, dict):
        raise SkillError("frontmatter 必须是键值映射。")
    return data, text[match.end() :]


def load_skill(path: Path) -> SkillInfo:
    """读取并校验单个 ``SKILL.md``。"""
    if not path.is_file():
        raise SkillError(f"文件不存在：{path}")
    try:
        text = path.read_text(encoding="utf-8")
    except OSError as exc:
        raise SkillError(f"读取失败：{path}（{exc}）") from exc

    data, body = parse_frontmatter(text, source=path)

    name = data.get("name")
    if not isinstance(name, str) or not name.strip():
        raise SkillError(f"{path}：frontmatter 缺少非空的 name。")
    name = name.strip()
    if not _NAME_PATTERN.match(name):
        raise SkillError(
            f"{path}：name={name!r} 不合法，要求小写短横线命名（如 example-echo）。"
        )

    description = data.get("description")
    if not isinstance(description, str) or not description.strip():
        raise SkillError(
            f"{path}：frontmatter 缺少非空的 description。"
            "描述决定模型何时加载该 Skill，请写清「做什么 + 什么时候用」。"
        )

    extra = {
        key: value for key, value in data.items() if key not in {"name", "description"}
    }

    info = SkillInfo(name=name, description=description.strip(), path=path, body=body.strip())
    object.__setattr__(info, "_extra", extra)
    return info


def discover_skills(
    roots: Iterable[Path],
    *,
    strict: bool = False,
) -> tuple[list[SkillInfo], list[str]]:
    """扫描若干根目录，返回 ``(已发现的 Skill, 错误列表)``。

    Args:
        roots: 根目录列表；目录本身或其后代含有 ``SKILL.md`` 均会被发现，
            但不会深入已经命中的 Skill 目录。
        strict: ``True`` 时遇到非法 Skill 直接抛 :class:`SkillError`。

    Returns:
        按 ``name`` 排序的 Skill 列表，以及所有校验/读取错误的消息。
    """
    found: dict[str, SkillInfo] = {}
    errors: list[str] = []

    for root in roots:
        if not root.is_dir():
            logger.debug("skills.root_missing", root=str(root))
            continue
        for skill_file in sorted(root.rglob(SKILL_FILENAME)):
            try:
                info = load_skill(skill_file)
            except SkillError as exc:
                if strict:
                    raise
                errors.append(str(exc))
                logger.warning("skills.invalid", path=str(skill_file), error=str(exc))
                continue
            existing = found.get(info.name)
            if existing is not None:
                message = (
                    f"Skill 名称重复：{info.name}（{existing.path} 与 {info.path}），保留前者。"
                )
                errors.append(message)
                logger.warning("skills.duplicate_name", name=info.name, kept=str(existing.path))
                continue
            found[info.name] = info

    return [found[name] for name in sorted(found)], errors


__all__ = [
    "SKILL_FILENAME",
    "SkillError",
    "SkillInfo",
    "discover_skills",
    "load_skill",
    "parse_frontmatter",
]

