    """处理只读的斜杠命令；返回 ``False`` 表示应退出 REPL。

    需要访问存储的命令（``/new`` / ``/history``）由 :meth:`_handle_async_command`
    处理 —— 它们要走 ``HistoryStore``，是异步的。
    """
    name = command.split(maxsplit=1)[0].lower()

    if name in {"/exit", "/quit"}:
