def _with_tools(settings: Settings, yaml_fragment: str) -> Settings:
    """在已有配置上追加 ``agent.tools`` 片段，返回新配置。

    直接改 YAML 再重新加载，比手工构造 Settings 更能反映真实读取路径。
    """
    import yaml

    raw = settings.app.model_dump(mode="json")
    fragment = yaml.safe_load(f"agent:\n{yaml_fragment}\n")["agent"]
    raw["agent"] = {**raw["agent"], **fragment}
    if "disabled" in fragment or "enabled_groups" in fragment:
        # 这些键属于 tools 段，纠正一下位置。
        raw.setdefault("tools", {})
        for key in ("disabled", "enabled_groups"):
            if key in fragment:
                raw["tools"][key] = fragment.pop(key)
        raw["agent"] = {**settings.app.agent.model_dump(mode="json"), **fragment}
    from doudou.config.schema import AppConfig

    return settings.model_copy(update={"app": AppConfig.model_validate(raw)})


def _tool_by_name(tools: list[BaseTool], name: str) -> BaseTool:
    found = find_tool(tools, name)
    assert found is not None
    return found

