def _summary(text: str, limit: int = 44) -> str:
    """把工具的 docstring 压成表格可用的单行摘要。

    只取**首行**：工具的 docstring 首行本来就是一句话说明，
    后面的 ``Args:`` / ``Returns:`` 是给模型看的，塞进表格只会把行高撑爆。
    """
    stripped = text.strip()
    if not stripped:
        return ""
    return truncate(stripped.splitlines()[0].strip(), limit)

