    if flattened != content:
        # CallToolResult 是 pydantic 模型，字段可赋值。
        try:
            result.content = flattened  # type: ignore[misc]
        except (AttributeError, ValueError):  # pragma: no cover - 只读模型
            logger.debug("mcp.flatten_skipped", result_type=type(result).__name__)
    return result


def blocks_to_text(content: Any) -> Any:
    """内容块列表 → 单个字符串；已经是字符串时原样返回。"""
    if isinstance(content, str) or content is None:
        return content
    if not isinstance(content, list):
        return content

    parts: list[str] = []
    for block in content:
        if isinstance(block, str):
            parts.append(block)
            continue
        block_type = ""
        text = ""
        if isinstance(block, dict):
            block_type = str(block.get("type") or "")
            text = str(block.get("text") or "")
        else:
            block_type = str(getattr(block, "type", "") or "")
            text = str(getattr(block, "text", "") or "")
        if text:
            parts.append(text)
        elif block_type:
            parts.append(_placeholder(block_type))

    if not parts:
        return content
    # 块之间用空行分隔：多数 MCP 工具返回的多个块是不同段落。
    return "\n\n".join(parts)


def _placeholder(block_type: str) -> str:
    mapping = {
        "image": "[图片内容，当前无法作为文本使用]",
        "audio": "[音频内容，当前无法作为文本使用]",
        "resource": "[资源引用]",
        "resource_link": "[资源链接]",
    }
    return mapping.get(block_type, f"[{block_type} 内容]")


class FlattenContentInterceptor:
    """``ToolCallInterceptor``：调用结束后把结果拍平。

    用适配器官方的扩展点，而不是自己包一层工具 —— 包壳会丢掉 args_schema，
    模型看到的工具定义就残了。
    """

    async def __call__(
        self,
        request: Any,
        handler: Any,
    ) -> Any:
        result = await handler(request)
        return flatten_result(result)


